// Process each language
const langs = ['de', 'fr', 'es', 'it', 'nl', 'pl'];

for (const lang of langs) {
  const filePath = path.join(msgDir, `${lang}.json`);
  const raw = fs.readFileSync(filePath, 'utf8');
  
  // Parse JSON to ensure it's valid and get the data
  const data = JSON.parse(raw);
  
  // Add new translations
  const langTrans = translations[lang];
  for (const [key, value] of Object.entries(langTrans)) {
    data[key] = value;
  }
  
  // Write back with nice formatting
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + '\n', 'utf8');
  
  // Validate
  const reread = fs.readFileSync(filePath, 'utf8');
  JSON.parse(reread); // Will throw if invalid
  
  // Count keys
  const parsed = JSON.parse(reread);
  const newKeys = Object.keys(parsed).filter(k => k.startsWith('scenarios.') || k.startsWith('reviews.'));
  console.log(`✅ ${lang}.json: ${Object.keys(parsed).length} total keys, ${newKeys.length} scenarios/reviews keys`);
}

console.log('\n🎉 All translations added and validated!');
